#!/usr/bin/env node
// tools/run-tests.mjs — runs the real test suite, parses the TAP `# pass` /
// `# fail` lines, and writes data/test-results.js. No human types the test
// count anywhere in this repo: the UI's Self-Test Strip and both writeups
// read it from this generated file.

import { spawnSync } from "node:child_process";
import { writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const __dirname = dirname(fileURLToPath(import.meta.url));
const ROOT = join(__dirname, "..");
const OUT_PATH = join(ROOT, "data", "test-results.js");

function main() {
  // --test-reporter=tap: Node's default reporter format varies by version and
  // is not reliably machine-parseable; TAP's "# pass N" / "# fail N" summary
  // lines are the stable, documented contract this script parses.
  const result = spawnSync(process.execPath, ["--test", "--test-reporter=tap"], {
    cwd: ROOT,
    encoding: "utf8",
  });

  const output = `${result.stdout || ""}${result.stderr || ""}`;
  const passMatch = output.match(/^# pass (\d+)$/m);
  const failMatch = output.match(/^# fail (\d+)$/m);
  const totalMatch = output.match(/^# tests (\d+)$/m);

  if (!passMatch || !failMatch || !totalMatch) {
    console.error("run-tests: could not parse TAP summary from `node --test` output");
    console.error(output);
    process.exit(1);
  }

  const pass = Number(passMatch[1]);
  const fail = Number(failMatch[1]);
  const total = Number(totalMatch[1]);

  const record = {
    pass,
    fail,
    total,
    ranAt: new Date().toISOString(),
    command: "npm test",
    dependencies: 0,
  };

  const body =
    "// data/test-results.js -- GENERATED by tools/run-tests.mjs (npm run testcount).\n" +
    "// The test count is computed here, never typed by hand, anywhere in this repo\n" +
    "// or in either writeup -- both read it from this file.\n\n" +
    `export default Object.freeze(${JSON.stringify(record, null, 2)});\n`;

  writeFileSync(OUT_PATH, body, "utf8");
  console.log(`data/test-results.js written: pass=${pass} fail=${fail} total=${total}`);

  if (fail !== 0) {
    console.error(`run-tests: ${fail} failing test(s) -- see output above`);
    process.exit(1);
  }
}

main();
